  await new Promise((resolve, reject) => {
    // Handle exceptions thrown by the worker thread.
    worker.addEventListener("error", e => {
      worker.terminate();
      reject(e);
    });

    // Handle updates from the worker thread.
    worker.addEventListener("message", e => {
      const { msg, percent } = e.data;
      onProgress?.(parseInt(percent, 10));
      if (msg == "success") {
        resolve(e.data);
        worker.terminate();
      }
    });

    // Kick off the worker.
    worker.postMessage({ path });
  });
}

try {
  folder.acquireSemaphore(folder, "folderPane.rebuildFolderSummary");
  await lazy.repairMbox(folder.filePath.path);
} catch (e) {
  console.warn(`Repair mbox FAILED; ${e.message}`);
} finally {
  folder.releaseSemaphore(folder, "folderPane.rebuildFolderSummary");
}
